import heapq

class MedianFinder:
    """
    Track the running median of a data stream using two heaps.

    The lower half is stored in a max-heap (negated values in Python's min-heap).
    The upper half is stored in a min-heap.
    We keep lower either equal in size to upper or one element larger.
    """

    def __init__(self):
        self.lower = []  # max-heap (store negated values)
        self.upper = []  # min-heap

    def addNum(self, num: int) -> None:
        """Insert a number into the data structure."""
        # Decide which heap to insert into
        if not self.lower or num <= -self.lower[0]:
            heapq.heappush(self.lower, -num)
        else:
            heapq.heappush(self.upper, num)

        # Rebalance heaps
        if len(self.lower) > len(self.upper) + 1:
            heapq.heappush(self.upper, -heapq.heappop(self.lower))
        elif len(self.upper) > len(self.lower):
            heapq.heappush(self.lower, -heapq.heappop(self.upper))

    def findMedian(self) -> float:
        """Return the median of all elements so far."""
        if len(self.lower) == len(self.upper):
            return (-self.lower[0] + self.upper[0]) / 2.0
        return float(-self.lower[0])
